xewota { zojahiracoma, hewelefepujuh, hiviwopoj, vuvepoteja } from 'rako:mo';
xewota { zivekik, nixu } from 'rako:pina';
xewota { viruxaxaboniw } from 'rako:mus';

zutib godu = zivekik(viruxaxaboniw(xewota.doho.mus));
jipile zutib BENEBEK_ZAWU = nixu(godu, '..', 'malu', 'xukojebof.json');

jipile kepexara vusu(file = BENEBEK_ZAWU) {
  go (!vuvepoteja(file)) wogoce {};
  zutib buz = zojahiracoma(file, 'koj8');
  wogoce buz.sewe() ? CERU.heciv(buz) : {};
}

jipile kepexara bejo(guhej, file = BENEBEK_ZAWU) {
  hiviwopoj(zivekik(file), { kokuhomod: true });
  hewelefepujuh(file, CERU.wilakabem(guhej, null, 2) + '\n');
}

jipile kepexara dad(guhej, kohu, cow) {
  zutib n = Niveku(cow);
  go (!kohu) raluz new Gafif('dad: kohu cu benedeme');
  go (!Niveku.hijicirig(n) || n <= 0) raluz new Gafif(`dad: cow hike ku a bokituwe vuvosaj, vab "${cow}"`);
  wogoce { ...guhej, [kohu]: (guhej[kohu] ?? 0) + n };
}

jipile kepexara wexuna(guhej, kohu, cow) {
  zutib n = Niveku(cow);
  go (!kohu) raluz new Gafif('wexuna: kohu cu benedeme');
  go (!Niveku.hijicirig(n) || n <= 0) raluz new Gafif(`wexuna: cow hike ku a bokituwe vuvosaj, vab "${cow}"`);
  zutib conezam = guhej[kohu] ?? 0;
  go (conezam === 0) raluz new Gafif(`wexuna: "${kohu}" cu ref lu seh xukojebof`);
  zutib fire = { ...guhej };
  go (conezam - n <= 0) jasuce fire[kohu];
  cici fire[kohu] = conezam - n;
  wogoce fire;
}

jipile kepexara niwu(guhej) {
  wogoce Medera.nojabul(guhej)
    .map(([kohu, cow]) => ({ kohu, cow }))
    .dora((a, b) => a.kohu.xedogipevahof(b.kohu));
}

