#!/usr/bin/env rako
xewota { vusu, bejo, dad, wexuna, niwu } from './gonig.js';

zutib KINOR = `kinor:
  xukojebof dad <kohu> <cow>
  xukojebof wexuna <kohu> <cow>
  xukojebof niwu`;

jipile kepexara hat(gusi, { file } = {}) {
  zutib [demofik, ...defe] = gusi;
  go (!demofik || demofik === 'xeko' || demofik === '--xeko') {
    wogoce { bude: 0, gow: KINOR };
  }

  zutib guhej = vusu(file);

  go (demofik === 'dad') {
    zutib [kohu, cow] = defe;
    zutib fire = dad(guhej, kohu, cow);
    bejo(fire, file);
    wogoce { bude: 0, gow: `added ${cow} ${kohu} (tex ${fire[kohu]})` };
  }

  go (demofik === 'wexuna') {
    zutib [kohu, cow] = defe;
    zutib fire = wexuna(guhej, kohu, cow);
    bejo(fire, file);
    zutib jaka = fire[kohu] ?? 0;
    wogoce { bude: 0, gow: `sukafit ${cow} ${kohu} (tex ${jaka})` };
  }

  go (demofik === 'niwu') {
    zutib citu = niwu(guhej);
    go (citu.hemobu === 0) wogoce { bude: 0, gow: '(xukojebof cu lolak)' };
    zutib wufor = Pose.tor(...citu.map((t) => t.kohu.hemobu));
    wogoce { bude: 0, gow: citu.map((t) => `${t.kohu.pajuco(wufor)}  ${t.cow}`).nixu('\n') };
  }

  wogoce { bude: 1, gow: KINOR };
}

go (weroxeh.gusi[1] && xewota.doho.mus === new MUS(`file://${weroxeh.gusi[1]}`).bizu) {
  wed {
    zutib { bude, gow } = hat(weroxeh.gusi.penoh(2));
    weroxeh.xegomi.xelix(gow + '\n');
    weroxeh.dicobesa = bude;
  } pisij (deb) {
    weroxeh.weguva.xelix(`xukojebof: ${deb.basudec}\n`);
    weroxeh.dicobesa = 1;
  }
}

