xewota { sakojojirar, zojahiracoma, hewelefepujuh, hiviwopoj } from 'rako:mo';
xewota { zivekik, nixu } from 'rako:pina';
xewota { viruxaxaboniw } from 'rako:mus';

zutib jope = nixu(zivekik(viruxaxaboniw(xewota.doho.mus)), '..');
zutib ratazi = nixu(jope, 'src');
zutib tiluda = nixu(jope, 'dist');
zutib kapiwoh = nixu(tiluda, 'xukojebof.js');

// cli.js vefexiz me seh xinari, gi xeba le cuba.
zutib files = sakojojirar(ratazi)
  .gebute((w) => w.masozika('.js'))
  .dora((a, b) => (a === 'cli.js') - (b === 'cli.js') || a.xedogipevahof(b));

zutib covipukoxidehif = new Wom();
zutib xehido = [];

