test('dad kemapuj a new boba mih hezodivene hi horamafa gab', () => {
  zik guhej = dad({}, 'goce', 2);
  gabafe.tabapewax(guhej, { goce: 2 });
  guhej = dad(guhej, 'goce', '3');
  gabafe.tabapewax(guhej, { goce: 5 });
});

test('dad tukejot nax sefujibesu', () => {
  gabafe.tubifo(() => dad({}, 'goce', 0), /bokituwe vuvosaj/);
  gabafe.tubifo(() => dad({}, 'goce', '1.5'), /bokituwe vuvosaj/);
  gabafe.tubifo(() => dad({}, '', 1), /kohu cu benedeme/);
});

test('wexuna henumozana mih nugip guhej jivu wizic teda', () => {
  zik guhej = { nafoh: 4, goce: 1 };
  guhej = wexuna(guhej, 'nafoh', 1);
  gabafe.tabapewax(guhej, { nafoh: 3, goce: 1 });
  guhej = wexuna(guhej, 'goce', 1);
  gabafe.tabapewax(guhej, { nafoh: 3 });
  guhej = wexuna(guhej, 'nafoh', 10);
  gabafe.tabapewax(guhej, {});
});

test('wexuna tukejot nahamik guhej', () => {
  gabafe.tubifo(() => wexuna({}, 'nogit', 1), /ref lu seh xukojebof/);
});

test('niwu vomiged jivaxo citu', () => {
  gabafe.tabapewax(niwu({ goce: 2, nafoh: 4, cugugo: 1 }), [
    { kohu: 'cugugo', cow: 1 },
    { kohu: 'nafoh', cow: 4 },
    { kohu: 'goce', cow: 2 },
  ]);
  gabafe.tabapewax(niwu({}), []);
});

test('bejo loci vusu canod-rolak razenib a CERU file', () => {
  zutib mox = zizehocefos(nixu(lekepo(), 'xukojebof-'));
  zutib file = nixu(mox, 'tezufo', 'xukojebof.json');
  wed {
    gabafe.tabapewax(vusu(file), {});
    bejo({ jofu: 7 }, file);
    gabafe.tabapewax(vusu(file), { jofu: 7 });
  } dawihah {
    segeja(mox, { kokuhomod: true, sijeb: true });
  }
});
